def gen(rng):
    def fmt(n, edges, s):
        return '%d %d %d\n' % (n, len(edges), s) + '\n'.join('%d %d %d' % e for e in edges)

    def rand_graph(n, m, wmax, connected, s=None):
        edges = []
        if connected and n > 1:
            order = list(range(n))
            rng.shuffle(order)
            for i in range(1, n):
                edges.append((order[rng.randrange(i)], order[i], rng.randint(1, wmax)))
        while len(edges) < m and n > 1:
            u = rng.randrange(n)
            v = rng.randrange(n)
            if u != v:
                edges.append((u, v, rng.randint(1, wmax)))
        edges = edges[:m] if not connected else edges
        rng.shuffle(edges)
        return fmt(n, edges, rng.randrange(n) if s is None else s)

    tests = ['1 0 0\n', '2 1 1\n0 1 5', '3 0 2\n', '4 3 0\n0 1 5\n0 2 5\n0 3 2', '4 2 3\n0 1 1\n1 2 1',
             '3 3 1\n0 1 2\n1 2 2\n0 2 4']
    for _ in range(14):
        n = rng.randint(1, 8)
        m = rng.randint(0, 12)
        tests.append(rand_graph(n, m, rng.choice((3, 9)), rng.random() < 0.6))
    for _ in range(3):
        tests.append(rand_graph(2000, 5000, 1000, True))
    tests.append(rand_graph(2000, 1500, 1000, False))
    # max size cases
    tests.append(rand_graph(50000, 100000, 1000, True))
    path = [(i, i + 1, rng.randint(1, 1000)) for i in range(49999)]
    tests.append(fmt(50000, path, 25000))
    tests.append(rand_graph(50000, 100000, 1000, False))
    star = [(0, i, rng.randint(1, 1000)) for i in range(1, 50000)]
    tests.append(fmt(50000, star + [(1, 2, 1)] * 50000, 7))
    return tests
